// Turn the shared parser modules into classic scripts for MV3 content scripts.
// Chrome does not run content scripts as ES modules. Commit the generated files
// and keep them in sync with `npm run bundle-content`.

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const BUNDLES = [
  { source: "src/core/search-results.js", out: "src/content/search-results.classic.js" },
  { source: "src/core/search-box.js", out: "src/content/search-box.classic.js" },
  { source: "src/core/shop-page.js", out: "src/content/shop-page.classic.js" },
];

function exportNames(source) {
  const names = [];
  for (const match of source.matchAll(/^export\s+(?:async\s+)?function\s+([A-Za-z0-9_]+)/gm)) names.push(match[1]);
  for (const match of source.matchAll(/^export\s+(?:const|let|var)\s+([A-Za-z0-9_]+)/gm)) names.push(match[1]);
  return names;
}

export function bundleClassic(source) {
  const names = exportNames(source);
  let body = source.replace(/^\s*import\s+\{([^}]+)\}\s+from\s+["'][^"']+["'];?\s*$/gm, (_, imported) => {
    return imported
      .split(",")
      .map((part) => part.trim())
      .filter(Boolean)
      .map((name) => `const ${name} = globalThis.IscaleEtsy.${name};`)
      .join("\n");
  });
  body = body.replace(/^export\s+(async\s+function|function|const|let|var|class)\s+/gm, "$1 ");
  body = body.replace(/^export\s+\{[^}]+\};?\s*$/gm, "");
  const assignments = names.map((name) => `  api.${name} = ${name};`).join("\n");
  return `/* Generated by scripts/bundle-content.mjs. Do not edit. */
(function (root) {
  "use strict";
${body.trim()}
  var api = root.IscaleEtsy || (root.IscaleEtsy = {});
${assignments}
})(typeof globalThis !== "undefined" ? globalThis : this);
`;
}

export function bundleFiles(read = (path) => readFileSync(join(root, path), "utf8")) {
  return BUNDLES.map((entry) => ({
    ...entry,
    text: bundleClassic(read(entry.source)),
  }));
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === join(process.cwd(), process.argv[1]).replaceAll("\\", "/");
const invoked = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain || invoked) {
  mkdirSync(join(root, "src/content"), { recursive: true });
  for (const file of bundleFiles()) {
    writeFileSync(join(root, file.out), file.text);
  }
}
